def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change = new - old
    change_ratio = (change / old) * 100
    return {
        "value": change_ratio,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
